  370000000,
  $REC$quote_with_modifications$REC$,
  $J$[{"label": "Hail-stow deployment protocol", "match": ["hail-stow", "stow", "tracker", "SPC", "tilt"], "weight": 1}, {"label": "Hail sub-limit adequacy", "match": ["hail sub", "$25M", "$15M", "Munich Re", "sublimit"], "weight": 1}, {"label": "BESS thermal monitoring", "match": ["thermal", "runaway", "inter-enclosure", "monitoring", "sensor"], "weight": 1}, {"label": "BESS compartmentalization", "match": ["enclosure", "compartment", "containment", "perimeter", "LFP"], "weight": 1}, {"label": "TX Panhandle hail frequency", "match": ["Panhandle", "Texas", "hail", "frequency", "NOAA", "SPC"], "weight": 1}, {"label": "Lender / IE approval", "match": ["lender", "PPA", "independent engineer", "IE", "permitted endorsement"], "weight": 1}, {"label": "Tower structuring", "match": ["lead", "Lloyd", "Munich Re", "Swiss Re", "AXIS", "BESS-specific"], "weight": 1}, {"label": "Path forward", "match": ["Lloyd", "bind", "subject to", "approve"], "weight": 1}]$J$::jsonb,
  array[$I$Hail-stow not deployed timely$I$, $I$Inter-enclosure thermal monitoring gap$I$, $I$Munich Re hail sub-limit reduction$I$, $I$BESS thermal runaway event on file$I$]::text[],
  'published'
)
